add('同种元素形成不同单质与碳单质结构差异',[[135,287,360,185,520]],'研究表明，透明的金刚石、灰黑色的石墨和分子结构与足球相似的C₆₀都是由碳元素组成的单质，但是它们的原子排列方式不同，物理性质存在着明显差异。')
add('金刚石的性质与用途',[[135,432,640,185,520],[136,50,265]],notes=['第二页主要为图6-1结构及用途图，文字用下述专用选择。'])
